mapper.select:
SELECT a.ANALYSIS_ID, a.RECONCILIATION_ID, a.MODEL_ID, a.PERIOD, a.DIFF_REASON, a.DIFF_DESCRIPTION, a.SOLUTION, a.ADJUST_AMOUNT, a.STATUS, a.HANDLER, a.HANDLER_NAME, a.HANDLE_TIME, a.TENANT_ID, a.CREATE_USER, a.CREATE_TIME, a.UPDATE_USER, a.UPDATE_TIME, m.MODEL_NAME, r.COMPANY_A_NAME, r.COMPANY_B_NAME, r.DIFF_AMOUNT, r.TRANSACTION_TYPE FROM TBL_RECONCILIATION_ANALYSIS a LEFT JOIN TBL_CONSOLIDATION_MODEL m ON a.MODEL_ID = m.MODEL_ID LEFT JOIN TBL_RECONCILIATION_DATA r ON a.RECONCILIATION_ID = r.RECONCILIATION_ID
AND a.MODEL_ID = #{param.modelId}
AND a.PERIOD = #{param.period}
AND a.DIFF_REASON = #{param.diffReason}
AND a.STATUS = #{param.status}
AND a.HANDLER = #{param.handler}
AND r.COMPANY_A_NAME LIKE CONCAT('%', #{param.companyAName}, '%')
AND r.COMPANY_B_NAME LIKE CONCAT('%', #{param.companyBName}, '%')
ORDER BY a.CREATE_TIME DESC
